CREATE OR REPLACE FUNCTION "public"."group_id_for_schedule"("sid" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select group_id from weekly_schedules where id = sid;
$$;


ALTER FUNCTION "public"."group_id_for_schedule"("sid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."group_id_for_slot"("slid" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select ws.group_id from schedule_slots ss join weekly_schedules ws on ws.id = ss.schedule_id where ss.id = slid;
$$;


ALTER FUNCTION "public"."group_id_for_slot"("slid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_group_admin"("gid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from group_members gm
    where gm.group_id = gid
      and gm.status = 'active'
      and gm.role = 'admin'
      and (gm.student_id = auth.uid() or gm.parent_id = auth.uid())
  );
$$;


ALTER FUNCTION "public"."is_group_admin"("gid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_group_member"("gid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from group_members gm
    where gm.group_id = gid
      and gm.status = 'active'
      and (gm.student_id = auth.uid() or gm.parent_id = auth.uid())
  );
$$;


ALTER FUNCTION "public"."is_group_member"("gid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_parent_account"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from parents p where p.id = auth.uid());
$$;


ALTER FUNCTION "public"."is_parent_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_weekly_availability"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
begin
  if extract(dow from (now() at time zone 'America/New_York')) = 0
     and extract(hour from (now() at time zone 'America/New_York')) = 0 then
    delete from parent_availability where is_recurring = false;
  end if;
end;
$$;


ALTER FUNCTION "public"."reset_weekly_availability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shares_group_with"("other_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from group_members a join group_members b on a.group_id = b.group_id
    where (a.student_id = auth.uid() or a.parent_id = auth.uid())
      and (b.student_id = other_user_id or b.parent_id = other_user_id)
  );
$$;


ALTER FUNCTION "public"."shares_group_with"("other_user_id" "uuid") OWNER TO "postgres";

