CREATE POLICY "groups_delete" ON "public"."carpool_groups" FOR DELETE USING (("public"."is_group_admin"("id") OR ("created_by" = "auth"."uid"())));



CREATE POLICY "groups_insert" ON "public"."carpool_groups" FOR INSERT WITH CHECK (("created_by" = "auth"."uid"()));



CREATE POLICY "groups_read" ON "public"."carpool_groups" FOR SELECT USING (("public"."is_group_member"("id") OR ("created_by" = "auth"."uid"()) OR (EXISTS ( SELECT 1
   FROM "public"."group_invites" "gi"
  WHERE (("gi"."group_id" = "carpool_groups"."id") AND ("gi"."invited_student_id" = "auth"."uid"()))))));



CREATE POLICY "groups_update" ON "public"."carpool_groups" FOR UPDATE USING (("public"."is_group_admin"("id") OR ("created_by" = "auth"."uid"())));



CREATE POLICY "invites_delete" ON "public"."group_invites" FOR DELETE USING (("public"."is_group_admin"("group_id") OR ("invited_by" = "auth"."uid"())));



CREATE POLICY "invites_insert" ON "public"."group_invites" FOR INSERT WITH CHECK ((("invited_by" = "auth"."uid"()) AND "public"."is_group_member"("group_id")));



CREATE POLICY "invites_read" ON "public"."group_invites" FOR SELECT USING ((("invited_by" = "auth"."uid"()) OR ("invited_student_id" = "auth"."uid"())));



CREATE POLICY "invites_update" ON "public"."group_invites" FOR UPDATE USING (("invited_student_id" = "auth"."uid"()));



CREATE POLICY "members_delete" ON "public"."group_members" FOR DELETE USING ((("student_id" = "auth"."uid"()) OR ("parent_id" = "auth"."uid"()) OR "public"."is_group_admin"("group_id")));



CREATE POLICY "members_insert" ON "public"."group_members" FOR INSERT WITH CHECK ((("student_id" = "auth"."uid"()) AND ((EXISTS ( SELECT 1
   FROM "public"."carpool_groups" "cg"
  WHERE (("cg"."id" = "group_members"."group_id") AND ("cg"."created_by" = "auth"."uid"())))) OR (EXISTS ( SELECT 1
   FROM "public"."group_invites" "gi"
  WHERE (("gi"."group_id" = "group_members"."group_id") AND ("gi"."invited_student_id" = "auth"."uid"()) AND ("gi"."status" = 'accepted'::"text")))))));



CREATE POLICY "members_read" ON "public"."group_members" FOR SELECT USING ("public"."is_group_member"("group_id"));



CREATE POLICY "members_update" ON "public"."group_members" FOR UPDATE USING ((("student_id" = "auth"."uid"()) OR ("parent_id" = "auth"."uid"()) OR (EXISTS ( SELECT 1
   FROM "public"."parents" "p"
  WHERE (("p"."id" = "auth"."uid"()) AND ("p"."student_id" = "group_members"."student_id")))))) WITH CHECK ((("parent_id" = "auth"."uid"()) OR ("parent_id" IS NULL) OR ("student_id" = "auth"."uid"())));



CREATE POLICY "messages_insert" ON "public"."group_messages" FOR INSERT WITH CHECK ((("sender_id" = "auth"."uid"()) AND "public"."is_group_member"("group_id")));



CREATE POLICY "messages_read" ON "public"."group_messages" FOR SELECT USING ("public"."is_group_member"("group_id"));



